export interface Post {
  id: number
  title: string
  content: string
  createdAt: Date
}

const posts: Post[] = [
  {
    id: 1,
    title: "First Post",
    content: "Welcome to the blog!",
    createdAt: new Date("2025-01-01"),
  },
]

let nextId = 2

export function getPosts(): Post[] {
  return posts
}

export function createPost(title: string, content: string): Post {
  const post: Post = {
    id: nextId++,
    title,
    content,
    createdAt: new Date(),
  }
  posts.push(post)
  return post
}

